:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --focus: #f5c542;
  --pixel: 2px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1a2e 25%, #1f1f38 25%, #1f1f38 50%, #1a1a2e 50%, #1a1a2e 75%, #1f1f38 75%);
  background-size: 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: var(--pixel) solid var(--accent);
  box-shadow: 0 0 0 var(--pixel) var(--bg), 0 0 0 calc(var(--pixel) * 2) var(--accent);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  flex: 1 1 auto;
  min-width: 100px;
  padding: 10px 12px;
  font-size: 0.95rem;
  font-family: inherit;
  background: transparent;
  color: var(--muted);
  border: var(--pixel) solid var(--muted);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.mode-btn:hover {
  background: rgba(233, 69, 96, 0.1);
  color: var(--text);
  border-color: var(--accent);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.mode-btn.active {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  font-weight: 700;
}

.mode-btn:active {
  transform: translateY(1px);
}

.timer {
  font-size: clamp(3rem, 18vw, 5rem);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text);
  line-height: 1.1;
  padding: 8px 0;
  border-top: var(--pixel) dashed var(--muted);
  border-bottom: var(--pixel) dashed var(--muted);
}

.timer.break {
  color: var(--focus);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 auto;
  min-width: 110px;
  padding: 14px 16px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  background: transparent;
  color: var(--text);
  border: var(--pixel) solid var(--muted);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.05s;
}

.btn:hover {
  background: rgba(233, 69, 96, 0.15);
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(2px);
  background: rgba(233, 69, 96, 0.25);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.btn.primary:hover {
  background: #ff5c7a;
  border-color: #ff5c7a;
}

.btn.primary:active {
  background: #c7304a;
}

.hint {
  font-size: 0.8rem;
  color: var(--muted);
  letter-spacing: 0.5px;
}

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  .btn, .mode-btn { min-width: 0; }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const display = document.getElementById('timerDisplay');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workMode');
  const breakModeBtn = document.getElementById('breakMode');

  let mode = 'work';
  let remaining = WORK_SECONDS;
  let running = false;
  let endTime = 0;
  let intervalId = null;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    display.textContent = formatTime(remaining);
    display.classList.toggle('break', mode === 'break');
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
    workModeBtn.classList.toggle('active', mode === 'work');
    workModeBtn.setAttribute('aria-pressed', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
    breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  }

  function tick() {
    const now = Date.now();
    const diff = Math.max(0, Math.ceil((endTime - now) / 1000));
    if (diff !== remaining) {
      remaining = diff;
      render();
    }
    if (remaining <= 0) {
      stopTimer();
      switchMode(mode === 'work' ? 'break' : 'work');
    }
  }

  function startTimer() {
    if (running) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    intervalId = setInterval(tick, 200);
    render();
  }

  function stopTimer() {
    if (!running) return;
    running = false;
    clearInterval(intervalId);
    intervalId = null;
    render();
  }

  function toggleTimer() {
    if (running) {
      stopTimer();
    } else {
      startTimer();
    }
  }

  function resetTimer() {
    stopTimer();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  function switchMode(newMode) {
    stopTimer();
    mode = newMode;
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  startPauseBtn.addEventListener('click', toggleTimer);
  resetBtn.addEventListener('click', resetTimer);
  workModeBtn.addEventListener('click', function () { switchMode('work'); });
  breakModeBtn.addEventListener('click', function () { switchMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON' && (e.key === ' ' || e.key === 'Enter')) return;
    if (e.key === ' ') {
      e.preventDefault();
      toggleTimer();
    } else if (e.key === 'r' || e.key === 'R') {
      resetTimer();
    }
  });

  render();
})();
